#Instructions for displaying inspection results with a 0% pass rate

function passRate = calculatePassRate(inspectionResults)
    passCount = 0;
    totalCount = length(inspectionResults);

    for i = 1:totalCount
        if inspectionResults(i) == 'pass'
            passCount = passCount + 1;
        end
    end

    passRate = passCount / totalCount;
end

function displayResults(passRate)
    if passRate == 0
        fprintf('Inspection results show a 0% pass rate.\n');
    else 
        fprintf('Inspection results show a non-zero pass rate.\n');
    end
end

